import math
import seqmodel as sm

# ---- construction validation ----
for bad in [(0, 3), (2, 0), (-1, 3), (3, 2.0), (2.0, 3), (True, 3), (3, False)]:
    try:
        sm.BidirectionalGRU(*bad)
        raise AssertionError("FAIL no ValueError %r" % (bad,))
    except ValueError:
        pass
for badseed in [1.0, True, false := 0]:
    pass
for badseed in [1.0, True, False]:
    try:
        sm.BidirectionalGRU(3, 2, seed=badseed)
        raise AssertionError("FAIL seed %r" % (badseed,))
    except ValueError:
        pass

m = sm.BidirectionalGRU(3, 2, seed=5)
assert isinstance(m.forward_cell, sm.GRUCell)
assert isinstance(m.backward_cell, sm.GRUCell)
assert m.forward_cell.W == sm.GRUCell(3, 2, 5).W
assert m.backward_cell.W == sm.GRUCell(3, 2, 6).W

try:
    m.forward()
    raise AssertionError("FAIL arity forward")
except TypeError:
    pass

